import numpy as np

class ReLU:
    """ReLU activation function."""

    def __init__(self):
        pass

    def forward(self, x: np.ndarray) -> np.ndarray:
        """Forward pass: max(0, x)."""
        return np.maximum(0, x)

class LeakyReLU:
    """Leaky ReLU activation function."""

    def __init__(self, negative_slope: float = 0.01):
        self.negative_slope = negative_slope

    def forward(self, x: np.ndarray) -> np.ndarray:
        """Forward pass: x if x > 0 else negative_slope * x."""
        return np.where(x > 0, x, self.negative_slope * x)

class Sigmoid:
    """Sigmoid activation function."""

    def __init__(self):
        pass

    def forward(self, x: np.ndarray) -> np.ndarray:
        """Forward pass: 1 / (1 + exp(-x)). Numerically stable."""
        # Use numpy's expm1 for numerical stability with large values
        return 1.0 / (1.0 + np.exp(-x))
